const tabId = 1962625075;
const jobDetails = await browserjs(tabId, () => {
  const title = document.querySelector('h1')?.textContent.trim();
  const meta = document.querySelector('.job-meta, .meta, .header-container, .job-header')?.textContent.trim();
  const description = document.querySelector('.job-description, #job-description, .description')?.textContent.trim();

  // Extract all text sections / sidebar details
  const details = {};
  const dl = document.querySelectorAll('dl, .details, .info-section, .meta-info, [class*="detail"]');
  dl.forEach(d => {
    d.querySelectorAll('dt, h2, h3, h4, strong, span.label').forEach(label => {
      const val = label.nextElementSibling?.textContent.trim();
      if (val) details[label.textContent.trim()] = val;
    });
  });

  // Also collect all text from the main container
  const mainText = document.querySelector('main, #main, .main-content, body')?.innerText;

  return {
    title,
    meta,
    url: window.location.href,
    details,
    mainTextSummary: mainText?.slice(0, 3000)
  };
});
console.log(JSON.stringify(jobDetails, null, 2));

